use split_decls_genesis :: ourprelude :: * ; use std :: fmt :: Debug ; use std :: hash :: Hash ; use std :: mem ; use std :: ops :: Deref ; use rustc_index :: bit_set :: BitMatrix ; use crate :: frozen :: Frozen ; use crate :: fx :: { FxHashSet , FxIndexSet } ; #[cfg (test)] mod tests ; #[derive (Clone , Debug)] pub struct TransitiveRelationBuilder < T > { elements : FxIndexSet < T > , edges : FxHashSet < Edge > , } #[derive (Debug)] pub struct TransitiveRelation < T > { builder : Frozen < TransitiveRelationBuilder < T > > , closure : Frozen < BitMatrix < usize , usize > > , } impl < T > Deref for TransitiveRelation < T > { type Target = Frozen < TransitiveRelationBuilder < T > > ; fn deref (& self) -> & Self :: Target { & self . builder } } impl < T : Clone > Clone for TransitiveRelation < T > { fn clone (& self) -> Self { TransitiveRelation { builder : Frozen :: freeze (self . builder . deref () . clone ()) , closure : Frozen :: freeze (self . closure . deref () . clone ()) , } } } impl < T : Eq + Hash > Default for TransitiveRelationBuilder < T > { fn default () -> Self { TransitiveRelationBuilder { elements : Default :: default () , edges : Default :: default () } } } #[derive (Copy , Clone , PartialEq , Eq , PartialOrd , Debug , Hash)] struct Index (usize) ; #[derive (Clone , PartialEq , Eq , Debug , Hash)] struct Edge { source : Index , target : Index , } impl < T : Eq + Hash + Copy > TransitiveRelationBuilder < T > { pub fn is_empty (& self) -> bool { self . edges . is_empty () } pub fn elements (& self) -> impl Iterator < Item = & T > { self . elements . iter () } fn index (& self , a : T) -> Option < Index > { self . elements . get_index_of (& a) . map (Index) } fn add_index (& mut self , a : T) -> Index { let (index , _added) = self . elements . insert_full (a) ; Index (index) } #[doc = " Applies the (partial) function to each edge and returns a new"] #[doc = " relation builder. If `f` returns `None` for any end-point,"] #[doc = " returns `None`."] pub fn maybe_map < F , U > (& self , mut f : F) -> Option < TransitiveRelationBuilder < U > > where F : FnMut (T) -> Option < U > , U : Clone + Debug + Eq + Hash + Copy , { let mut result = TransitiveRelationBuilder :: default () ; for edge in & self . edges { result . add (f (self . elements [edge . source . 0]) ? , f (self . elements [edge . target . 0]) ?) ; } Some (result) } #[doc = " Indicate that `a < b` (where `<` is this relation)"] pub fn add (& mut self , a : T , b : T) { let a = self . add_index (a) ; let b = self . add_index (b) ; let edge = Edge { source : a , target : b } ; self . edges . insert (edge) ; } #[doc = " Compute the transitive closure derived from the edges, and converted to"] #[doc = " the final result. After this, all elements will be immutable to maintain"] #[doc = " the correctness of the result."] pub fn freeze (self) -> TransitiveRelation < T > { let mut matrix = BitMatrix :: new (self . elements . len () , self . elements . len ()) ; let mut changed = true ; while changed { changed = false ; for edge in & self . edges { changed |= matrix . insert (edge . source . 0 , edge . target . 0) ; changed |= matrix . union_rows (edge . target . 0 , edge . source . 0) ; } } TransitiveRelation { builder : Frozen :: freeze (self) , closure : Frozen :: freeze (matrix) } } } impl < T : Eq + Hash + Copy > TransitiveRelation < T > { #[doc = " Applies the (partial) function to each edge and returns a new"] #[doc = " relation including transitive closures."] pub fn maybe_map < F , U > (& self , f : F) -> Option < TransitiveRelation < U > > where F : FnMut (T) -> Option < U > , U : Clone + Debug + Eq + Hash + Copy , { Some (self . builder . maybe_map (f) ? . freeze ()) } #[doc = " Checks whether `a < target` (transitively)"] pub fn contains (& self , a : T , b : T) -> bool { match (self . index (a) , self . index (b)) { (Some (a) , Some (b)) => self . with_closure (| closure | closure . contains (a . 0 , b . 0)) , (None , _) | (_ , None) => false , } } #[doc = " Thinking of `x R y` as an edge `x -> y` in a graph, this"] #[doc = " returns all things reachable from `a`."] #[doc = ""] #[doc = " Really this probably ought to be `impl Iterator<Item = &T>`, but"] #[doc = " I'm too lazy to make that work, and -- given the caching"] #[doc = " strategy -- it'd be a touch tricky anyhow."] pub fn reachable_from (& self , a : T) -> Vec < T > { match self . index (a) { Some (a) => { self . with_closure (| closure | closure . iter (a . 0) . map (| i | self . elements [i]) . collect ()) } None => vec ! [] , } } #[doc = " Picks what I am referring to as the \"postdominating\""] #[doc = " upper-bound for `a` and `b`. This is usually the least upper"] #[doc = " bound, but in cases where there is no single least upper"] #[doc = " bound, it is the \"mutual immediate postdominator\", if you"] #[doc = " imagine a graph where `a < b` means `a -> b`."] #[doc = ""] #[doc = " This function is needed because region inference currently"] #[doc = " requires that we produce a single \"UB\", and there is no best"] #[doc = " choice for the LUB. Rather than pick arbitrarily, I pick a"] #[doc = " less good, but predictable choice. This should help ensure"] #[doc = " that region inference yields predictable results (though it"] #[doc = " itself is not fully sufficient)."] #[doc = ""] #[doc = " Examples are probably clearer than any prose I could write"] #[doc = " (there are corresponding tests below, btw). In each case,"] #[doc = " the query is `postdom_upper_bound(a, b)`:"] #[doc = ""] #[doc = " ```text"] #[doc = " // Returns Some(x), which is also LUB."] #[doc = " a -> a1 -> x"] #[doc = "            ^"] #[doc = "            |"] #[doc = " b -> b1 ---+"] #[doc = ""] #[doc = " // Returns `Some(x)`, which is not LUB (there is none)"] #[doc = " // diagonal edges run left-to-right."] #[doc = " a -> a1 -> x"] #[doc = "   \\/       ^"] #[doc = "   /\\       |"] #[doc = " b -> b1 ---+"] #[doc = ""] #[doc = " // Returns `None`."] #[doc = " a -> a1"] #[doc = " b -> b1"] #[doc = " ```"] pub fn postdom_upper_bound (& self , a : T , b : T) -> Option < T > { let mubs = self . minimal_upper_bounds (a , b) ; self . mutual_immediate_postdominator (mubs) } #[doc = " Viewing the relation as a graph, computes the \"mutual"] #[doc = " immediate postdominator\" of a set of points (if one"] #[doc = " exists). See `postdom_upper_bound` for details."] pub fn mutual_immediate_postdominator (& self , mut mubs : Vec < T >) -> Option < T > { loop { match mubs [..] { [] => return None , [mub] => return Some (mub) , _ => { let m = mubs . pop () . unwrap () ; let n = mubs . pop () . unwrap () ; mubs . extend (self . minimal_upper_bounds (n , m)) ; } } } } #[doc = " Returns the set of bounds `X` such that:"] #[doc = ""] #[doc = " - `a < X` and `b < X`"] #[doc = " - there is no `Y != X` such that `a < Y` and `Y < X`"] #[doc = "   - except for the case where `X < a` (i.e., a strongly connected"] #[doc = "     component in the graph). In that case, the smallest"] #[doc = "     representative of the SCC is returned (as determined by the"] #[doc = "     internal indices)."] #[doc = ""] #[doc = " Note that this set can, in principle, have any size."] pub fn minimal_upper_bounds (& self , a : T , b : T) -> Vec < T > { let (Some (mut a) , Some (mut b)) = (self . index (a) , self . index (b)) else { return vec ! [] ; } ; if a > b { mem :: swap (& mut a , & mut b) ; } let lub_indices = self . with_closure (| closure | { if closure . contains (a . 0 , b . 0) { return vec ! [b . 0] ; } if closure . contains (b . 0 , a . 0) { return vec ! [a . 0] ; } let mut candidates = closure . intersect_rows (a . 0 , b . 0) ; pare_down (& mut candidates , closure) ; candidates . reverse () ; pare_down (& mut candidates , closure) ; candidates }) ; lub_indices . into_iter () . rev () . map (| i | self . elements [i]) . collect () } #[doc = " Given an element A, returns the maximal set {B} of elements B"] #[doc = " such that"] #[doc = ""] #[doc = " - A != B"] #[doc = " - A R B is true"] #[doc = " - for each i, j: `B[i]` R `B[j]` does not hold"] #[doc = ""] #[doc = " The intuition is that this moves \"one step up\" through a lattice"] #[doc = " (where the relation is encoding the `<=` relation for the lattice)."] #[doc = " So e.g., if the relation is `->` and we have"] #[doc = ""] #[doc = " ```text"] #[doc = " a -> b -> d -> f"] #[doc = " |              ^"] #[doc = " +--> c -> e ---+"] #[doc = " ```"] #[doc = ""] #[doc = " then `parents(a)` returns `[b, c]`. The `postdom_parent` function"] #[doc = " would further reduce this to just `f`."] pub fn parents (& self , a : T) -> Vec < T > { let Some (a) = self . index (a) else { return vec ! [] ; } ; let ancestors = self . with_closure (| closure | { let mut ancestors = closure . intersect_rows (a . 0 , a . 0) ; ancestors . retain (| & e | ! closure . contains (e , a . 0)) ; pare_down (& mut ancestors , closure) ; ancestors . reverse () ; pare_down (& mut ancestors , closure) ; ancestors }) ; ancestors . into_iter () . rev () . map (| i | self . elements [i]) . collect () } #[doc = " Given an element A, elements B with the lowest index such that `A R B`"] #[doc = " and `B R A`, or `A` if no such element exists."] pub fn minimal_scc_representative (& self , a : T) -> T { match self . index (a) { Some (a_i) => self . with_closure (| closure | { closure . iter (a_i . 0) . find (| i | closure . contains (* i , a_i . 0)) . map_or (a , | i | self . elements [i]) }) , None => a , } } fn with_closure < OP , R > (& self , op : OP) -> R where OP : FnOnce (& BitMatrix < usize , usize >) -> R , { op (& self . closure) } #[doc = " Lists all the base edges in the graph: the initial _non-transitive_ set of element"] #[doc = " relations, which will be later used as the basis for the transitive closure computation."] pub fn base_edges (& self) -> impl Iterator < Item = (T , T) > { self . edges . iter () . map (move | edge | (self . elements [edge . source . 0] , self . elements [edge . target . 0])) } } #[doc = " Pare down is used as a step in the LUB computation. It edits the"] #[doc = " candidates array in place by removing any element j for which"] #[doc = " there exists an earlier element i<j such that i -> j. That is,"] #[doc = " after you run `pare_down`, you know that for all elements that"] #[doc = " remain in candidates, they cannot reach any of the elements that"] #[doc = " come after them."] #[doc = ""] #[doc = " Examples follow. Assume that a -> b -> c and x -> y -> z."] #[doc = ""] #[doc = " - Input: `[a, b, x]`. Output: `[a, x]`."] #[doc = " - Input: `[b, a, x]`. Output: `[b, a, x]`."] #[doc = " - Input: `[a, x, b, y]`. Output: `[a, x]`."] fn pare_down (candidates : & mut Vec < usize > , closure : & BitMatrix < usize , usize >) { let mut i = 0 ; while let Some (& candidate_i) = candidates . get (i) { i += 1 ; let mut j = i ; let mut dead = 0 ; while let Some (& candidate_j) = candidates . get (j) { if closure . contains (candidate_i , candidate_j) { dead += 1 ; } else { candidates [j - dead] = candidate_j ; } j += 1 ; } candidates . truncate (j - dead) ; } }